import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import CertificateDesigner from '../common/components/CertificateDesigner';
import { forumDesign, saveForumDesign } from '../common/api';
const t = key => app.translator.trans(`ernestdefoe-syllabus.admin.certificate.${key}`);

/** The forum's default certificate design: courses use it for every part they leave empty. */
export default class CertificateSetting extends Component {
  design = null;
  saving = false;
  dirty = false;
  oninit(vnode) {
    super.oninit(vnode);
    forumDesign().then(({
      data
    }) => {
      this.design = data;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "Form-group SyllabusCertificateSetting"
    }, m("label", null, t('heading')), m("div", {
      className: "helpText"
    }, t('help')), this.design ? m('[', null, m(CertificateDesigner, {
      design: this.design,
      onchange: () => this.dirty = true
    }), m(Button, {
      className: "Button Button--primary",
      loading: this.saving,
      disabled: !this.dirty,
      onclick: () => this.save()
    }, t('save'))) : m(LoadingIndicator, null));
  }
  save() {
    const design = this.design;
    this.saving = true;
    saveForumDesign({
      template: design.template,
      signerName: design.signerName,
      signerTitle: design.signerTitle
    }).then(({
      data
    }) => {
      this.saving = false;
      this.dirty = false;
      Object.assign(design, data);
      app.alerts.show({
        type: 'success'
      }, t('saved'));
      m.redraw();
    }, () => {
      this.saving = false;
      m.redraw();
    });
  }
}